{
  "root_causes": [
    {
      "service": "rate",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT time, attr_k8s_pod_name, metric, value FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'rate%' AND metric IN ('k8s.container.ready','k8s.container.restarts') ORDER BY time",
          "claim": "The rate pod stayed not-ready (ready=0) while its restart count climbed from 2 to 6 during the incident window."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, count(*) n, avg(value) v FROM abnormal_metrics WHERE metric='k8s.deployment.available' GROUP BY metric UNION ALL SELECT 'normal:'||metric, count(*), avg(value) FROM normal_metrics WHERE metric='k8s.deployment.available' GROUP BY metric",
          "claim": "rate's deployment shows zero available replicas in the abnormal period versus one in the normal period."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) n FROM abnormal_traces WHERE span_name='rate.Rate/GetRates' GROUP BY ALL",
          "claim": "rate server spans nearly disappear (3 in abnormal) while search's GetRates client spans fail 1100 times with Error status."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "rate",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) n, quantile_cont(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates' GROUP BY ALL",
          "claim": "search's calls to rate fail fast with Error status (p50 about 0.01 ms, 1100 spans) while successful calls are only 4."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('HTTP /hotels','search.Search/Nearby') GROUP BY ALL",
          "claim": "frontend's search.Search/Nearby calls error ~1100 times and its HTTP /hotels requests return 500 in the abnormal window."
        }
      ]
    }
  ]
}
